export default {
    name: "goodsAudit",
    data() {
        return {
            pendingGoods: [],
            currentPage: 1,
            pageSize: 8,
            total: 0
        }
    },
    created() {
        this.getPendingGoods();
    },
    methods: {
        getPendingGoods() {
            this.$api.admin({
                url: 'getPendingGoods',
                method: 'get',
                params: {
                    page: this.currentPage,
                    nums: this.pageSize
                }
            }).then(res => {
                if (res.status_code === 1) {
                    this.pendingGoods = res.data.list;
                    this.total = res.data.count;
                } else {
                    this.$message.error(res.msg || '获取待审核商品失败');
                }
            }).catch(err => {
                console.error(err);
                this.$message.error('获取待审核商品失败');
            });
        },
        handleCurrentChange(val) {
            this.currentPage = val;
            this.getPendingGoods();
        },
        handleApprove(row) {
            this.$confirm('确认通过该商品的发布申请?', '提示', {
                confirmButtonText: '确定',
                cancelButtonText: '取消',
                type: 'success'
            }).then(() => {
                this.approveGoods(row.id, true);
            }).catch(() => {
                // 取消操作
            });
        },
        handleReject(row) {
            this.$confirm('确认拒绝该商品的发布申请? 该操作将删除此商品的所有数据。', '警告', {
                confirmButtonText: '确定',
                cancelButtonText: '取消',
                type: 'warning'
            }).then(() => {
                this.approveGoods(row.id, false);
            }).catch(() => {
                // 取消操作
            });
        },
        approveGoods(goodsId, approved) {
            this.$api.admin({
                url: 'approveGoods',
                method: 'get',
                params: {
                    id: goodsId,
                    approved: approved
                }
            }).then(res => {
                if (res.status_code === 1) {
                    this.$message({
                        type: 'success',
                        message: approved ? '已通过商品发布申请' : '已拒绝商品发布申请'
                    });
                    this.getPendingGoods(); // 刷新列表
                } else {
                    this.$message.error(res.msg || '操作失败');
                }
            }).catch(err => {
                console.error(err);
                this.$message.error('操作失败');
            });
        },
        getFirstImage(pictureList) {
            try {
                if (pictureList) {
                    const images = JSON.parse(pictureList);
                    if (images && images.length > 0) {
                        return this.$store.state.baseApi + images[0];
                    }
                }
                return '';
            } catch (e) {
                return '';
            }
        },
        formatTime(timeStr) {
            if (timeStr) {
                return timeStr.substring(0, 10) + " " + timeStr.substring(11, 19);
            }
            return '';
        }
    }
}
